use std::process::Command;
fn parse(text:&str)->Vec<(u64,String)>{let mut rows:Vec<_>=text.lines().filter_map(|l|{let(a,b)=l.split_once('\t')?;Some((a.parse::<u64>().ok()?,b.to_string()))}).collect();rows.sort_by(|a,b|b.0.cmp(&a.0).then(a.1.cmp(&b.1)));rows}
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<_>=std::env::args().skip(1).collect();if args.iter().any(|a|a=="--help"){println!("package-footprint [NAME_SUBSTRING]\nRead-only Debian-family dpkg installed-size ranking in KiB, top 50 matches.");return Ok(())}if !cfg!(target_os="linux"){return Err("Linux/dpkg required".into())}if args.len()>1{return Err("Only one optional name filter".into())}let output=Command::new("dpkg-query").args(["-W","-f=${Installed-Size}\t${binary:Package}\n"]).env("LC_ALL","C").output()?;if !output.status.success(){return Err("dpkg-query failed".into())}let rows=parse(&String::from_utf8_lossy(&output.stdout));let filter=args.first().map(|s|s.to_lowercase()).unwrap_or_default();let total:u64=rows.iter().map(|r|r.0).sum();println!("Total declared installed footprint: {total} KiB");for(size,name)in rows.into_iter().filter(|r|r.1.to_lowercase().contains(&filter)).take(50){println!("{size:>12} KiB  {name}");}Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn sorts_and_skips_invalid(){assert_eq!(parse("12\ta\n400\tb\nnope\tx\n"),vec![(400,"b".into()),(12,"a".into())]);}}
